{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2175-12-29 11:00:00",
      "speaker": "Doctor",
      "text": "Good morning. I’m Dr. Lee, one of your hospital doctors. You’re here today for your 14th cycle of high-dose methotrexate for your brain lymphoma. How are you feeling?"
    },
    {
      "turn_number": 2,
      "time": "2175-12-29 11:02:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. I’m okay. A little nervous, but no headaches or nausea yet."
    },
    {
      "turn_number": 3,
      "time": "2175-12-29 11:03:00",
      "speaker": "Doctor",
      "text": "That’s good. We’ll give you anti-nausea meds before the chemo to help prevent that. We also reviewed your MRI from last time."
    },
    {
      "turn_number": 4,
      "time": "2175-12-29 11:04:00",
      "speaker": "Patient",
      "text": "Oh, right. The headaches I had before—was it the lymphoma again?"
    },
    {
      "turn_number": 5,
      "time": "2175-12-29 11:05:00",
      "speaker": "Doctor",
      "text": "No, the lymphoma looks stable—no new growth. But your sinuses, especially on the right side, are more inflamed. That’s likely what caused the headaches."
    },
    {
      "turn_number": 6,
      "time": "2175-12-29 11:06:00",
      "speaker": "Patient",
      "text": "Oh, I didn’t even have a runny nose. Just pressure."
    },
    {
      "turn_number": 7,
      "time": "2175-12-29 11:07:00",
      "speaker": "Doctor",
      "text": "Exactly. Sinus infections don’t always cause discharge. We’re starting you on an antibiotic called clindamycin—safe for your penicillin allergy."
    },
    {
      "turn_number": 8,
      "time": "2175-12-29 11:08:00",
      "speaker": "Patient",
      "text": "Okay. But I’ve had diarrhea with antibiotics before."
    },
    {
      "turn_number": 9,
      "time": "2175-12-29 11:09:00",
      "speaker": "Doctor",
      "text": "Good point. If you get diarrhea, stop the antibiotic and call your neuro-oncologist right away. We don’t want a serious gut infection."
    },
    {
      "turn_number": 10,
      "time": "2175-12-29 11:10:00",
      "speaker": "Patient",
      "text": "Got it. And my aspirin—I’ve been taking it daily. Should I keep that up?"
    },
    {
      "turn_number": 11,
      "time": "2175-12-29 11:11:00",
      "speaker": "Doctor",
      "text": "We’ve held it during your stay to help your body clear the methotrexate faster. You’ll restart it tomorrow when you go home."
    },
    {
      "turn_number": 12,
      "time": "2175-12-29 11:12:00",
      "speaker": "Patient",
      "text": "And before my next chemo?"
    },
    {
      "turn_number": 13,
      "time": "2175-12-29 11:13:00",
      "speaker": "Doctor",
      "text": "Stop it two days before your next admission. That’s what your neuro-oncologist recommended to stay safe."
    },
    {
      "turn_number": 14,
      "time": "2175-12-29 11:14:00",
      "speaker": "Patient",
      "text": "Okay, I’ll mark that on my calendar."
    },
    {
      "turn_number": 15,
      "time": "2175-12-29 12:15:00",
      "speaker": "Doctor",
      "text": "We’ve just finished giving your methotrexate through the port. You did great—no issues during the infusion."
    },
    {
      "turn_number": 16,
      "time": "2175-12-29 12:16:00",
      "speaker": "Patient",
      "text": "That’s over already? I didn’t feel a thing."
    },
    {
      "turn_number": 17,
      "time": "2175-12-29 12:17:00",
      "speaker": "Doctor",
      "text": "Yes, it takes a few hours, but you were resting. We’re giving you IV fluids with sodium acetate to help protect your kidneys."
    },
    {
      "turn_number": 18,
      "time": "2175-12-29 12:18:00",
      "speaker": "Patient",
      "text": "I remember last time they used bicarbonate. Is this the same?"
    },
    {
      "turn_number": 19,
      "time": "2175-12-29 12:19:00",
      "speaker": "Doctor",
      "text": "Similar goal—keeping your urine alkaline so the drug clears safely. We’re using sodium acetate because there’s a national shortage of IV bicarb."
    },
    {
      "turn_number": 20,
      "time": "2175-12-29 12:20:00",
      "speaker": "Patient",
      "text": "Ah, okay. Makes sense."
    },
    {
      "turn_number": 21,
      "time": "2175-12-30 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs look good. Creatinine clearance is strong at 123 mL/min, so your kidneys are handling the methotrexate well."
    },
    {
      "turn_number": 22,
      "time": "2175-12-30 09:01:00",
      "speaker": "Patient",
      "text": "That’s good. I’ve been a little nauseous, though."
    },
    {
      "turn_number": 23,
      "time": "2175-12-30 09:02:00",
      "speaker": "Doctor",
      "text": "Moderate nausea is common. We’ll give you prochlorperazine to help. Any vomiting?"
    },
    {
      "turn_number": 24,
      "time": "2175-12-30 09:03:00",
      "speaker": "Patient",
      "text": "No, just queasy."
    },
    {
      "turn_number": 25,
      "time": "2175-12-30 09:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep the anti-nausea meds going. Also, your liver enzymes are a bit up, but that’s expected—it’s called transaminitis and usually resolves."
    },
    {
      "turn_number": 26,
      "time": "2175-12-30 09:05:00",
      "speaker": "Patient",
      "text": "It happens every time. Should I be worried?"
    },
    {
      "turn_number": 27,
      "time": "2175-12-30 09:06:00",
      "speaker": "Doctor",
      "text": "Not at this level. We monitor it closely. It’s mild and not affecting your function."
    },
    {
      "turn_number": 28,
      "time": "2175-12-30 09:07:00",
      "speaker": "Patient",
      "text": "Okay, thanks."
    },
    {
      "turn_number": 29,
      "time": "2175-12-31 10:00:00",
      "speaker": "Doctor",
      "text": "Your methotrexate levels are dropping nicely. That means your body is clearing it well. No sign of toxicity."
    },
    {
      "turn_number": 30,
      "time": "2175-12-31 10:01:00",
      "speaker": "Patient",
      "text": "And the leucovorin?"
    },
    {
      "turn_number": 31,
      "time": "2175-12-31 10:02:00",
      "speaker": "Doctor",
      "text": "You started it yesterday, 24 hours after chemo. It helps ‘rescue’ your healthy cells from the chemo effects."
    },
    {
      "turn_number": 32,
      "time": "2175-12-31 10:03:00",
      "speaker": "Patient",
      "text": "I remember. It makes me a little tired, but I’d rather that than feeling sick."
    },
    {
      "turn_number": 33,
      "time": "2175-12-31 10:04:00",
      "speaker": "Doctor",
      "text": "Exactly. We’ll keep giving it until we’re sure the methotrexate is out of your system."
    },
    {
      "turn_number": 34,
      "time": "2175-12-31 14:00:00",
      "speaker": "Patient",
      "text": "Doctor, my right foot is really burning today. Worse than usual."
    },
    {
      "turn_number": 35,
      "time": "2175-12-31 14:02:00",
      "speaker": "Doctor",
      "text": "I see. We’ve kept your gabapentin going. It’s still chronic nerve pain, likely unrelated to the lymphoma. We can try adjusting the dose if it’s not helping."
    },
    {
      "turn_number": 36,
      "time": "2175-12-31 14:03:00",
      "speaker": "Patient",
      "text": "Maybe later. I don’t want to get too drowsy."
    },
    {
      "turn_number": 37,
      "time": "2175-12-31 14:04:00",
      "speaker": "Doctor",
      "text": "Fair. Use the oxycodone for breakthrough pain, but sparingly. We’re watching that closely after your last hospitalization."
    },
    {
      "turn_number": 38,
      "time": "2175-12-31 14:05:00",
      "speaker": "Patient",
      "text": "I understand. I’m feeling much more stable now. No thoughts like before."
    },
    {
      "turn_number": 39,
      "time": "2175-12-31 14:06:00",
      "speaker": "Doctor",
      "text": "I’m glad to hear that. You’re on citalopram, and your mood seems steady. Keep in touch with your psychiatrist."
    },
    {
      "turn_number": 40,
      "time": "2175-12-31 14:07:00",
      "speaker": "Patient",
      "text": "I will. I’ve learned I need that support."
    },
    {
      "turn_number": 41,
      "time": "2176-01-01 08:00:00",
      "speaker": "Doctor",
      "text": "Good news—you’re ready to go home today. Your labs are stable, you’ve cleared the chemo, and you’re doing well."
    },
    {
      "turn_number": 42,
      "time": "2176-01-01 08:01:00",
      "speaker": "Patient",
      "text": "That’s great. What about the sinus antibiotic?"
    },
    {
      "turn_number": 43,
      "time": "2176-01-01 08:02:00",
      "speaker": "Doctor",
      "text": "You’ll take clindamycin for 21 days. Full course. But stop it and call your doctor if you get diarrhea."
    },
    {
      "turn_number": 44,
      "time": "2176-01-01 08:03:00",
      "speaker": "Patient",
      "text": "Got it. And my other meds?"
    },
    {
      "turn_number": 45,
      "time": "2176-01-01 08:04:00",
      "speaker": "Doctor",
      "text": "Resume everything: gabapentin, citalopram, your asthma inhalers. But hold mesalamine for your colitis—it can interact with methotrexate."
    },
    {
      "turn_number": 46,
      "time": "2176-01-01 08:05:00",
      "speaker": "Patient",
      "text": "Okay, I’ll check with my GI doctor about that."
    },
    {
      "turn_number": 47,
      "time": "2176-01-01 08:06:00",
      "speaker": "Doctor",
      "text": "Good idea. Also, restart aspirin today. Then stop it two days before your next chemo."
    },
    {
      "turn_number": 48,
      "time": "2176-01-01 08:07:00",
      "speaker": "Patient",
      "text": "I’ll write that down. Thank you for going over everything."
    },
    {
      "turn_number": 49,
      "time": "2176-01-01 08:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. You did really well this cycle—no major complications. Just keep up with follow-up and call if anything changes."
    },
    {
      "turn_number": 50,
      "time": "2176-01-01 08:09:00",
      "speaker": "Patient",
      "text": "I will. I’m feeling hopeful."
    },
    {
      "turn_number": 51,
      "time": "2176-01-01 08:10:00",
      "speaker": "Doctor",
      "text": "That’s the best sign of all. Take care, and we’ll see you next cycle."
    },
    {
      "turn_number": 52,
      "time": "2176-01-01 08:11:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 53,
      "time": "2176-01-01 08:12:00",
      "speaker": "Doctor",
      "text": "Nurse will bring your discharge papers and prescriptions shortly."
    },
    {
      "turn_number": 54,
      "time": "2176-01-01 08:13:00",
      "speaker": "Patient",
      "text": "Okay, I’ll wait for them."
    },
    {
      "turn_number": 55,
      "time": "2176-01-01 08:14:00",
      "speaker": "Doctor",
      "text": "One last thing—drink plenty of fluids today to help flush out any remaining medication."
    },
    {
      "turn_number": 56,
      "time": "2176-01-01 08:15:00",
      "speaker": "Patient",
      "text": "I’ll make sure to do that."
    },
    {
      "turn_number": 57,
      "time": "2176-01-01 08:16:00",
      "speaker": "Doctor",
      "text": "And use the acetaminophen for any headache. Avoid ibuprofen or other NSAIDs."
    },
    {
      "turn_number": 58,
      "time": "2176-01-01 08:17:00",
      "speaker": "Patient",
      "text": "Right, because of the methotrexate."
    },
    {
      "turn_number": 59,
      "time": "2176-01-01 08:18:00",
      "speaker": "Doctor",
      "text": "Exactly. You know the drill. Great job this week."
    },
    {
      "turn_number": 60,
      "time": "2176-01-01 08:19:00",
      "speaker": "Patient",
      "text": "Thanks for taking such good care of me."
    },
    {
      "turn_number": 61,
      "time": "2176-01-01 08:20:00",
      "speaker": "Doctor",
      "text": "It’s our pleasure. Get some rest and we’ll see you soon."
    },
    {
      "turn_number": 62,
      "time": "2176-01-01 08:21:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 63,
      "time": "2176-01-01 08:22:00",
      "speaker": "Doctor",
      "text": "Take care."
    },
    {
      "turn_number": 64,
      "time": "2176-01-01 08:23:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 65,
      "time": "2176-01-01 08:24:00",
      "speaker": "Doctor",
      "text": "Nurse will assist you with discharge soon."
    },
    {
      "turn_number": 66,
      "time": "2176-01-01 08:25:00",
      "speaker": "Patient",
      "text": "Okay, thanks again."
    },
    {
      "turn_number": 67,
      "time": "2176-01-01 08:26:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Have a safe trip home."
    }
  ],
  "summary": {
    "admission_start": "2175-12-29 10:31:00",
    "admission_end": "2176-01-01 14:05:00",
    "summary_paragraph": "A 50-year-old woman with primary central nervous system lymphoma, ulcerative colitis, asthma, and a history of DVT/PE was admitted for her 14th cycle of high-dose methotrexate chemotherapy. She tolerated the treatment well with only moderate nausea, managed with anti-emetics. MRI showed stable lymphoma but worsening right-sided sinusitis, prompting a 21-day course of clindamycin. Her chronic right foot pain persisted, managed with gabapentin and PRN oxycodone. She remained emotionally stable on citalopram, with no suicidal ideation. Aspirin was held during admission to enhance methotrexate clearance and was restarted at discharge. She cleared methotrexate without renal or hepatic complications and was discharged home in stable condition with follow-up instructions.",
    "problems": [
      "Encounter for antineoplastic chemotherapy",
      "Other malignant lymphomas, unspecified site, extranodal and solid organ sites",
      "Ulcerative colitis, unspecified",
      "Disorders of phosphorus metabolism",
      "Personal history of venous thrombosis and embolism",
      "Personal history of pulmonary embolism",
      "Asthma, unspecified type, unspecified",
      "Unspecified sinusitis (chronic)",
      "Nonspecific elevation of levels of transaminase or lactic acid dehydrogenase [LDH]",
      "Other musculoskeletal symptoms referable to limbs"
    ]
  }
}
